pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address key) internal {
        uint256 beforeKey;
        try c.balances(key) returns (uint256 __r) { beforeKey = __r; } catch { return; }
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        uint256 afterKey;
        try c.balances(key) returns (uint256 __r) { afterKey = __r; } catch { return; }
        assertTrue(afterKey <= beforeKey && (reverted || afterKey == 0 || beforeKey != 0));
    }

    function testFuzz_run(address key) public {
        vm.assume(key.code.length == 0 && uint160(key) > 0xffff && key != address(this) && key != address(c) && key != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && key != 0x000000000000000000636F6e736F6c652e6c6f67 && key != 0x4e59b44847b379578588920cA78FbF26c0B4956C && key != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(key);
    }

    receive() external payable {}
}
